#include "volume_mod.h"
#include <math.h>
#include <stdlib.h>
#include <string.h>

/* 底层 volume 上下文 (向后兼容保留) */
typedef struct {
    double volume;
    int scaler_initialized;   /* volume_set 走完整路径后置 1 */
} VolumeContext;

struct VolumeModContext {
    double player_volume;
    PrecisionType precision;
    int nb_outputs;
    VolumeContext *vol_ctx;
    double *output_volume;     /* NAN = 未设置 */
};

VolumeModContext *ff_volume_alloc(void){
    VolumeModContext *s = calloc(1, sizeof(*s));
    if(!s) return NULL;
    s->player_volume = 1.0;
    s->precision = PRECISION_FIXED;
    return s;
}

int ff_volume_prealloc(VolumeModContext *s, int nb_outputs){
    if(!s || nb_outputs<=0) return -1;
    s->nb_outputs = nb_outputs;
    s->output_volume = malloc(sizeof(double)*nb_outputs);
    s->vol_ctx = calloc(nb_outputs, sizeof(VolumeContext));
    if(!s->output_volume || !s->vol_ctx) return -1;
    for(int i=0;i<nb_outputs;i++) s->output_volume[i] = NAN; /* 哨兵 */
    return 0;
}

static void vc_init(VolumeContext *vc){
    vc->volume = 1.0;            /* 默认 1.0 */
    vc->scaler_initialized = 0; /* scaler 未就绪 */
}
static void vc_set(VolumeContext *vc, double v){
    vc->volume = v;
    vc->scaler_initialized = 1; /* 走完整路径 */
}

int ff_volume_init(VolumeModContext *s, int nb_outputs){
    if(!s) return -1;
    if(nb_outputs>0 && nb_outputs!=s->nb_outputs){
        /* 重新分配 */
        if(ff_volume_prealloc(s, nb_outputs)<0) return -1;
    }
    for(int i=0;i<s->nb_outputs;i++){
        vc_init(&s->vol_ctx[i]);
        if(!isnan(s->output_volume[i]))
            vc_set(&s->vol_ctx[i], s->player_volume * s->output_volume[i]);
    }
    return 0;
}

void ff_volume_uninit(VolumeModContext *s){
    if(!s) return;
    free(s->vol_ctx); s->vol_ctx = NULL;   /* 释放 vol_ctx */
    /* 关键:保留 output_volume[],跨 unlink/link 循环 */
}

void ff_volume_free(VolumeModContext **s){
    if(!s || !*s) return;
    free((*s)->vol_ctx);
    free((*s)->output_volume);
    free(*s);
    *s = NULL;   /* 双指针置空,防悬空 */
}

void ff_volume_scale(VolumeModContext *s, int index, double *frame, int n){
    if(!s||!s->vol_ctx) return;
    double v = s->vol_ctx[index].volume;
    for(int i=0;i<n;i++) frame[i] *= v;
}

int ff_volume_set_output_volume(VolumeModContext *s, int index, double volume){
    if(!s) return -1;
    int lo = index<0?0:index, hi = index<0?s->nb_outputs:index+1;
    for(int i=lo;i<hi;i++){
        s->output_volume[i] = volume;
        if(s->vol_ctx)   /* 已 init 才同步 */
            vc_set(&s->vol_ctx[i], s->player_volume * volume); /* 统一语义 */
    }
    return 0;
}

void ff_volume_set_player_volume(VolumeModContext *s, double player_volume){
    if(!s) return;
    s->player_volume = player_volume;
    if(!s->vol_ctx) return;
    for(int i=0;i<s->nb_outputs;i++)
        if(!isnan(s->output_volume[i]))
            vc_set(&s->vol_ctx[i], s->player_volume * s->output_volume[i]);
}

double ff_volume_get_output_volume(VolumeModContext *s, int index){
    if(!s||index<0||index>=s->nb_outputs) return NAN;
    return s->output_volume[index];
}
double ff_volume_get_player_volume(VolumeModContext *s){
    return s?s->player_volume:NAN;
}
```

