#include "volume_mod.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define ROUTE_OFF 0
#define ROUTE_ON  1

struct MappingContext {
    char *map_str;
    int *map;
    int nb_outputs;
};

static int parse_mapping(const char *s, int *out, int n){
    /* 简化:逗号分隔, "1,0" */
    for(int i=0;i<n;i++) out[i]=ROUTE_OFF;
    if(!s) return 0;
    int idx=0; int val=0; int has=0;
    for(const char *p=s; ; ++p){
        if(*p==','||*p=='\0'){
            if(idx<n) out[idx]=has?val:ROUTE_OFF;
            idx++; val=0; has=0;
            if(*p=='\0') break;
        } else if(*p>='0'&&*p<='9'){ val=val*10+(*p-'0'); has=1; }
    }
    return 0;
}

MappingContext *ff_mapping_alloc(void){
    MappingContext *s = calloc(1,sizeof(*s));
    return s;
}
int ff_mapping_init(MappingContext *s, int nb_outputs){
    if(!s||nb_outputs<=0) return -1;
    s->nb_outputs=nb_outputs;
    s->map=calloc(nb_outputs,sizeof(int));
    for(int i=0;i<nb_outputs;i++) s->map[i]=ROUTE_OFF;
    return 0;
}
void ff_mapping_free(MappingContext **s){
    if(!s||!*s) return;
    free((*s)->map_str);
    free((*s)->map);
    free(*s); *s=NULL;
}
int ff_mapping_is_enabled(MappingContext *s, int index){
    if(!s||!s->map||index<0||index>=s->nb_outputs) return 0;
    return s->map[index]==ROUTE_ON;
}
int ff_mapping_update(MappingContext *s, const char *map_str){
    if(!s) return -1;
    free(s->map_str);
    s->map_str = map_str?strdup(map_str):NULL;
    if(!s->map) return 0;
    return parse_mapping(map_str, s->map, s->nb_outputs);
}
const int *ff_mapping_get_map(MappingContext *s){
    return s?s->map:NULL;
}
