    for (const char *p = s; ; ++p) {
        if (*p == ',' || *p == '\0') {
            if (idx < n) out[idx] = has ? (val ? ROUTE_ON : ROUTE_OFF) : ROUTE_OFF;
            idx++; val = 0; has = 0;
            if (*p == '\0') break;
        } else if (*p >= '0' && *p <= '9') {
            val = val * 10 + (*p - '0'); has = 1;
        }
    }
    return 0;
}

MappingContext *ff_mapping_alloc(void)
{
    return calloc(1, sizeof(MappingContext));
}

int ff_mapping_init(MappingContext *s, int nb_outputs)
{
    if (!s || nb_outputs <= 0) return -1;
    s->nb_outputs = nb_outputs;
    s->map = calloc(nb_outputs, sizeof(int));
    for (int i = 0; i < nb_outputs; i++) s->map[i] = ROUTE_OFF;
    return 0;
}

void ff_mapping_free(MappingContext **s)
{
    if (!s || !*s) return;
    free((*s)->map_str);
    free((*s)->map);
    free(*s); *s = NULL;  /* 双指针,防悬空 */
}

int ff_mapping_is_enabled(MappingContext *s, int index)
{
    if (!s || !s->map || index < 0 || index >= s->nb_outputs) return 0;
    return s->map[index] == ROUTE_ON;
}

/* 诉求点(map):内部安全释放旧数组再分配,避免 use-after-free */
int ff_mapping_update(MappingContext *s, const char *map_str)
{
    if (!s) return -1;
    free(s->map_str);
    s->map_str = map_str ? strdup(map_str) : NULL;
    if (!s->map) return 0;
    return parse_mapping(map_str, s->map, s->nb_outputs);
}

const int *ff_mapping_get_map(MappingContext *s)
{
    return s ? s->map : NULL;
}

#include "volume_mod.h"
#include <assert.h>
#include <math.h>
#include <stddef.h>
#include <stdio.h>

/* 诉求点 1:filter 私有只持模块指针,无 volume[]/map/player_volume/precision 字段 */
typedef struct {
    VolumeModContext *vol;      /* 唯一 volume 入口 */
    MappingContext   *mapping;  /* 唯一 map 入口 */
} FilterPriv;

/* 诉求点 3:模拟 child class — filter 经 child_next 暴露 volume 模块 */
static void *filter_child_next(void *obj, void *prev)
{
    FilterPriv *s = obj;
    return prev ? NULL : s->vol;
}

static int approx(double a, double b) { return fabs(a - b) < 1e-9; }

/* ---- 实验 1:收敛参数 ---- */
static void exp1_converge(void)
{
    printf("[exp1] 收敛参数\n");
    FilterPriv f = { ff_volume_alloc(), ff_mapping_alloc() };
    /* filter 私有只有两个指针;volume/map 字段都在模块内 */
    assert(sizeof(f) == 2 * sizeof(void *));
    assert(sizeof(f) == sizeof(void *) + sizeof(void *));
    ff_volume_prealloc(f.vol, 2);
    ff_volume_init(f.vol, 2);
    ff_mapping_init(f.mapping, 2);
    /* child_next 取到 volume 模块 */
    void *child = filter_child_next(&f, NULL);
    assert(child == f.vol);
    /* precision 经模块取,filter 无 precision 字段 */
    assert(ff_volume_get_precision(f.vol) == PRECISION_FIXED);
    printf("  OK sizeof(FilterPriv)=%zu (2 ptr), child_next→vol, precision@module\n",
           sizeof(f));
    ff_volume_free(&f.vol);
    ff_mapping_free(&f.mapping);
    assert(f.vol == NULL && f.mapping == NULL);
}

/* ---- 实验 2:统一生命周期(unlink/link 循环保留) ---- */
static void exp2_lifecycle(void)
{
    printf("[exp2] 统一生命周期\n");
    VolumeModContext *v = ff_volume_alloc();
    ff_volume_prealloc(v, 2);
    ff_volume_init(v, 2);
    ff_volume_set_output_volume(v, 0, 0.8);
    double before = ff_volume_get_output_volume(v, 0);
    double eff0   = ff_volume_get_effective_volume(v, 0);

    /* 模拟 unlink:uninit 释放 vol_ctx,保留 output_volume[] */
    ff_volume_uninit(v);
    /* output_volume 在 uninit 后仍在(诉求点 2 核心) */
    double after_uninit = ff_volume_get_output_volume(v, 0);
    assert(approx(after_uninit, 0.8));

    /* 模拟 link:重新 init,output_volume[] 仍生效 */
    ff_volume_init(v, 2);
    double eff1 = ff_volume_get_effective_volume(v, 0);
    assert(approx(eff1, 0.8));   /* player=1.0 × 0.8 */
    printf("  OK before=%g eff0=%g | uninit→out_vol=%g | reinit eff1=%g\n",
           before, eff0, after_uninit, eff1);
    ff_volume_free(&v);
}

/* ---- 实验 3:AVOption 下沉 ---- */
static void exp3_avoption(void)
{
    printf("[exp3] AVOption 下沉\n");
    FilterPriv f = { ff_volume_alloc(), NULL };
    ff_volume_prealloc(f.vol, 1);
    ff_volume_init(f.vol, 1);
    /* precision 仅在 VolumeModContext;FilterPriv 无 precision 字段
       (若尝试 f.precision 会编译失败 — 不透明封装证据) */
    assert(ff_volume_get_precision(f.vol) == PRECISION_FIXED);
    /* child_next 链路暴露模块,配置直达 */
    assert(filter_child_next(&f, NULL) == f.vol);
    assert(filter_child_next(&f, (void*)1) == NULL); /* prev 非空返回 NULL */
    printf("  OK precision@VolumeModContext, child_next 链路 OK\n");
    ff_volume_free(&f.vol);
}

/* ---- 实验 4:语义一致(player × output_volume) ---- */
static void exp4_semantics(void)
{
    printf("[exp4] 语义一致\n");
    VolumeModContext *v = ff_volume_alloc();
    ff_volume_prealloc(v, 1);
    ff_volume_init(v, 1);
    ff_volume_set_player_volume(v, 0.5);
    ff_volume_set_output_volume(v, 0, 0.8);

    double eff = ff_volume_get_effective_volume(v, 0);
    /* 诉求点 4:有效音量 = player_volume(0.5) × output_volume(0.8) = 0.4
       重构前 abufsrc 漏乘 player_volume 会得 0.8 */
    assert(approx(eff, 0.4));
    assert(!approx(eff, 0.8));   /* 确认不是漏乘的错误值 */

    /* 用 scale 间接验证端到端 */
    double frame[2] = {1.0, 2.0};
    ff_volume_scale(v, 0, frame, 2);
    assert(approx(frame[0], 0.4) && approx(frame[1], 0.8));
    printf("  OK player=0.5 × out=0.8 → eff=0.4 (非漏乘 0.8); scale [1,2]→[0.4,0.8]\n");
    ff_volume_free(&v);
}

/* ---- 额外:map 模块安全 update ---- */
static void exp5_mapping(void)
{
    printf("[exp5] mapping 安全 update\n");
    MappingContext *m = ff_mapping_alloc();
    ff_mapping_init(m, 3);
    ff_mapping_update(m, "1,0,1");
    assert(ff_mapping_is_enabled(m, 0) == 1);
    assert(ff_mapping_is_enabled(m, 1) == 0);
    assert(ff_mapping_is_enabled(m, 2) == 1);
    /* 动态更新:旧数组安全释放,新值就绪 */
    ff_mapping_update(m, "0,1,0");
    assert(ff_mapping_is_enabled(m, 0) == 0);
    assert(ff_mapping_is_enabled(m, 1) == 1);
    assert(ff_mapping_is_enabled(m, 2) == 0);
    printf("  OK map=1,0,1 → [1,0,1]; update→[0,1,0]\n");
    ff_mapping_free(&m);
    assert(m == NULL);
}

int main(void)
{
    exp1_converge();
    exp2_lifecycle();
    exp3_avoption();
    exp4_semantics();
    exp5_mapping();
    printf("\nALL ASSERTS PASSED\n");
    return 0;
}

