308	void volume_scale(VolumeContext *vol, AVFrame *frame)
309	{
310	    int planar, planes, plane_size, p, need_convert, ret;
311	    AVFrame *proc_frame = frame;
312	
313	    if (!vol || !frame)
314	        return;
315	
316	    planar = av_sample_fmt_is_planar(frame->format);
317	    planes = planar ? frame->ch_layout.nb_channels : 1;
318	    plane_size = frame->nb_samples * (planar ? 1 : frame->ch_layout.nb_channels);
319	    need_convert = (vol->mid_fmt != frame->format);
320	
321	    if (vol->volume_last < 0)
322	        vol->volume_last = vol->volume; /* If volume not set after init, skip fade in first frame. */
323	
324	    /* convert to intermediate format if needed */
325	    if (need_convert) {
326	        proc_frame = get_conv_frame(vol, frame, vol->mid_fmt);
327	        if (!proc_frame) {
328	            av_log(NULL, AV_LOG_ERROR, "get_conv_frame failed\n");
329	            return;
330	        }
331	
332	        ret = bit_convert(frame->format, vol->mid_fmt,
333	                         planar ? (const void *)frame->extended_data : frame->data[0],
334	                         av_sample_fmt_is_planar(vol->mid_fmt) ? (void *)proc_frame->extended_data : proc_frame->data[0],
335	                         frame->nb_samples, frame->ch_layout.nb_channels);
336	        if (ret < 0) {
337	            av_log(NULL, AV_LOG_ERROR, "Convert to mid format failed\n");
338	            return;
339	        }
340	    }
341	
342	    /* apply volume scaling / fading */
343	    if (is_fixed(proc_frame->format)) {
344	        int32_t vol_isrc = (int32_t)lround(vol->volume_last * 256);
345	        int32_t volume_i = (int32_t)lround(vol->volume * 256);
346	        if (volume_i != vol_isrc) {
347	            for (p = 0; p < planes; p++) {
348	                vol->fade_samples(proc_frame->extended_data[p],
349	                                  proc_frame->extended_data[p],
350	                                  proc_frame->nb_samples, planar ? 1 : proc_frame->ch_layout.nb_channels,
351	                                  volume_i, vol_isrc);
352	            }
353	        } else {
354	            for (p = 0; p < planes; p++) {
355	                vol->scale_samples(proc_frame->extended_data[p],
356	                                   proc_frame->extended_data[p],
357	                                   plane_size, volume_i);
358	            }
359	        }
360	        vol->volume_last = vol->volume;
361	    } else if (is_float(proc_frame->format)) {
362	        for (p = 0; p < planes; p++) {
363	            vol->fdsp->vector_fmul_scalar((float *)proc_frame->extended_data[p],
364	                                          (float *)proc_frame->extended_data[p],
365	                                          vol->volume, plane_size);
366	        }
367	    } else {
368	        for (p = 0; p < planes; p++) {
369	            vol->fdsp->vector_dmul_scalar((double *)proc_frame->extended_data[p],
370	                                          (double *)proc_frame->extended_data[p],
371	                                          vol->volume, plane_size);
372	        }
373	    }
374	
375	    /* convert back to original format if needed */
376	    if (need_convert) {
377	        ret = bit_convert(vol->mid_fmt, frame->format,
378	                         av_sample_fmt_is_planar(vol->mid_fmt) ? (const void *)proc_frame->extended_data : proc_frame->data[0],
379	                         planar ? (void *)frame->extended_data : frame->data[0],
380	                         frame->nb_samples, frame->ch_layout.nb_channels);
381	        if (ret < 0) {
382	            av_log(NULL, AV_LOG_ERROR, "Convert to original format failed\n");
383	            return;
384	        }
385	    }
386	}
