388	int volume_init(VolumeContext *vol, enum AVSampleFormat sample_fmt, enum PrecisionType precision)
389	{
390	    if (!vol) {
391	        av_log(NULL, AV_LOG_ERROR, "VolumeContext is NULL\n");
392	        return AVERROR(EINVAL);
393	    }
394	
395	    vol->sample_fmt = sample_fmt;
396	    vol->precision = precision;
397	    vol->volume_last = -1.0f;
398	    vol->volume = 1.0f;
399	
400	    av_frame_free(&vol->conv_frame);
401	    vol->conv_frame = av_frame_alloc();
402	    if (!vol->conv_frame)
403	        return AVERROR(ENOMEM);
404	
405	    vol->mid_fmt = pick_mid_fmt(sample_fmt, precision);
406	
407	    if (vol->fdsp)
408	        av_freep(&vol->fdsp);
409	
410	    vol->fdsp = avpriv_float_dsp_alloc(0);
411	    if (!vol->fdsp) {
412	        av_frame_free(&vol->conv_frame);
413	        return AVERROR(ENOMEM);
414	    }
415	
416	    scaler_init(vol);
417	    fader_init(vol);
418	    return 0;
419	}
