```c

/* ============================================================ *
 * 模块化 VolumeModContext(诉求点 1/2/3/4)
 * 保留底层 volume_init/set/scale/uninit,向后兼容。
 * ============================================================ */

struct VolumeModContext {
    const struct AVClass *class;
    double player_volume;          /* 全局 player 音量乘数 */
    enum PrecisionType precision;  /* AVOption 下沉到此(诉求点 3)*/
    int nb_outputs;
    VolumeContext *vol_ctx;        /* per-output 底层上下文 */
    double *output_volume;         /* NAN = 未设置(哨兵)*/
};

static const AVOption ff_volume_options[] = {
    { "precision", "select mathematical precision",
      offsetof(VolumeModContext, precision), AV_OPT_TYPE_INT,
      { .i64 = PRECISION_FIXED }, PRECISION_FIXED, PRECISION_DOUBLE,
      AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_FILTERING_PARAM, "precision" },
    { "fixed",  "select 8-bit fixed-point",     0, AV_OPT_TYPE_CONST,
      { .i64 = PRECISION_FIXED  }, INT_MIN, INT_MAX,
      AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_FILTERING_PARAM, "precision" },
    { "float",  "select 32-bit floating-point", 0, AV_OPT_TYPE_CONST,
      { .i64 = PRECISION_FLOAT  }, INT_MIN, INT_MAX,
      AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_FILTERING_PARAM, "precision" },
    { "double", "select 64-bit floating-point", 0, AV_OPT_TYPE_CONST,
      { .i64 = PRECISION_DOUBLE }, INT_MIN, INT_MAX,
      AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_FILTERING_PARAM, "precision" },
    { NULL },
};

static const AVClass ff_volume_mod_class = {
    .class_name = "VolumeMod",
    .item_name  = av_default_item_name,
    .option     = ff_volume_options,
    .version    = LIBAVUTIL_VERSION_INT,
    .category   = AV_CLASS_CATEGORY_FILTER,
};

const AVClass *ff_volume_get_class(void)
{
    return &ff_volume_mod_class;
}

VolumeModContext *ff_volume_alloc(void)
{
    VolumeModContext *s = av_calloc(1, sizeof(*s));
    if (!s)
        return NULL;
    s->class        = &ff_volume_mod_class;
    s->player_volume = 1.0;
    s->precision    = PRECISION_FIXED;
    return s;
}

int ff_volume_prealloc(VolumeModContext *s, int nb_outputs)
{
    int i;
    if (!s || nb_outputs <= 0)
        return AVERROR(EINVAL);
    s->nb_outputs    = nb_outputs;
    s->output_volume = av_calloc(nb_outputs, sizeof(*s->output_volume));
    if (!s->output_volume)
        return AVERROR(ENOMEM);
    for (i = 0; i < nb_outputs; i++)
        s->output_volume[i] = NAN;  /* 哨兵:未设置 */
    return 0;
}

int ff_volume_init(VolumeModContext *s, int nb_outputs,
                   enum AVSampleFormat sample_fmt)
{
    int i, ret;
    if (!s)
        return AVERROR(EINVAL);
    if (nb_outputs > 0 && nb_outputs != s->nb_outputs)
        if (ff_volume_prealloc(s, nb_outputs) < 0)
            return AVERROR(ENOMEM);
    /* 诉求点 2:uninit 后 vol_ctx 已释放,link 再 init 时重建 */
    if (!s->vol_ctx)
        s->vol_ctx = av_calloc(s->nb_outputs, sizeof(*s->vol_ctx));
    if (!s->vol_ctx)
        return AVERROR(ENOMEM);
    for (i = 0; i < s->nb_outputs; i++) {
        ret = volume_init(&s->vol_ctx[i], sample_fmt, s->precision);
        if (ret < 0)
            return ret;
        if (!isnan(s->output_volume[i]))
            /* 诉求点 4:统一走 volume_set 完整路径,player × output */
            volume_set(&s->vol_ctx[i],
                       s->player_volume * s->output_volume[i]);
    }
    return 0;
}

void ff_volume_uninit(VolumeModContext *s)
{
    int i;
    if (!s)
        return;
    if (s->vol_ctx) {
        for (i = 0; i < s->nb_outputs; i++)
            volume_uninit(&s->vol_ctx[i]);  /* 释放底层内部资源 */
        av_freep(&s->vol_ctx);              /* 释放数组 */
    }
    /* 关键:保留 output_volume[],跨 unlink/link 循环 */
}

void ff_volume_free(VolumeModContext **s)
{
    if (!s || !*s)
        return;
    ff_volume_uninit(*s);
    av_freep(&(*s)->output_volume);
    av_freep(s);  /* 双指针置空,防悬空 */
}

void ff_volume_scale(VolumeModContext *s, int index, AVFrame *frame)
{
    if (!s || !s->vol_ctx || index < 0 || index >= s->nb_outputs)
        return;
    volume_scale(&s->vol_ctx[index], frame);
}

int ff_volume_set_output_volume(VolumeModContext *s, int index, double volume)
{
    int i, lo, hi;
    if (!s)
        return AVERROR(EINVAL);
    lo = index < 0 ? 0 : index;
    hi = index < 0 ? s->nb_outputs : index + 1;
    for (i = lo; i < hi; i++) {
        s->output_volume[i] = volume;
        if (s->vol_ctx)
            /* 诉求点 4:统一 player_volume × output_volume(修复漏乘)*/
            volume_set(&s->vol_ctx[i], s->player_volume * volume);
    }
    return 0;
}

void ff_volume_set_player_volume(VolumeModContext *s, double player_volume)
{
    int i;
    if (!s)
        return;
    s->player_volume = player_volume;
    if (!s->vol_ctx)
        return;
    for (i = 0; i < s->nb_outputs; i++)
        if (!isnan(s->output_volume[i]))
            volume_set(&s->vol_ctx[i],
                       s->player_volume * s->output_volume[i]);
}

double ff_volume_get_output_volume(VolumeModContext *s, int index)
{
    if (!s || index < 0 || index >= s->nb_outputs)
        return NAN;
    return s->output_volume[index];
}

double ff_volume_get_player_volume(VolumeModContext *s)
{
    return s ? s->player_volume : NAN;
}
```

