 * ============================================================ */

struct MappingContext {
    const struct AVClass *class;
    char *map_str;     /* AVOption:用户输入的 map 字符串(诉求点 3)*/
    int   *map;        /* 解析后的数组(ff_mapping_update 安全替换)*/
    int   nb_outputs;
};

static const AVOption ff_mapping_options[] = {
    { "map", "output routing",
      offsetof(MappingContext, map_str), AV_OPT_TYPE_STRING,
      { .str = NULL }, 0, 0,
      AV_OPT_FLAG_AUDIO_PARAM | AV_OPT_FLAG_FILTERING_PARAM },
    { NULL },
};

static const AVClass ff_mapping_class = {
    .class_name = "MappingMod",
    .item_name  = av_default_item_name,
    .option     = ff_mapping_options,
    .version    = LIBAVUTIL_VERSION_INT,
    .category   = AV_CLASS_CATEGORY_FILTER,
};

const AVClass *ff_mapping_get_class(void)
{
    return &ff_mapping_class;
}

MappingContext *ff_mapping_alloc(void)
{
    MappingContext *s = av_calloc(1, sizeof(*s));
    if (s)
        s->class = &ff_mapping_class;
    return s;
}

int ff_mapping_init(MappingContext *s, int nb_outputs)
{
    if (!s || nb_outputs <= 0)
        return AVERROR(EINVAL);
    s->nb_outputs = nb_outputs;
    s->map = av_calloc(nb_outputs, sizeof(*s->map));
    if (!s->map)
        return AVERROR(ENOMEM);
    /* 默认全 OFF */
    return 0;
}

void ff_mapping_free(MappingContext **s)
{
    if (!s || !*s)
        return;
    av_freep(&(*s)->map_str);
    av_freep(&(*s)->map);
    av_freep(s);   /* 双指针置空,防悬空 */
}

int ff_mapping_is_enabled(MappingContext *s, int index)
{
    if (!s || !s->map || index < 0 || index >= s->nb_outputs)
        return 0;
    return s->map[index] == ROUTE_ON;
}

int ff_mapping_update(MappingContext *s, const char *map_str)
{
    int ret;
    if (!s)
        return AVERROR(EINVAL);
    /* 安全释放旧 map_str,再 dup 新 */
    av_freep(&s->map_str);
    if (map_str) {
        s->map_str = av_strdup(map_str);
        if (!s->map_str)
            return AVERROR(ENOMEM);
    }
    if (!s->map)
        return 0;
    /* avfilter_parse_mapping 内部安全释放旧数组 + 重新分配,避免悬空 */
    ret = avfilter_parse_mapping(s->map_str, &s->map, s->nb_outputs);
    return ret;
}

const int *ff_mapping_get_map(MappingContext *s)
{
    return s ? s->map : NULL;
}

